import{z as B,x as i,o as l,c as d,q as r,j as n,D as E,d as t,s as o,S as s,b as e}from"./chunks/framework.C8m1ZpeB.js";const c=JSON.parse('{"title":"诚实性评测","description":"","frontmatter":{"title":"诚实性评测","date":"2026-09-18T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/aeval-honesty-eval.md","filePath":"llm/aeval-honesty-eval.md","lastUpdated":1791063341000}'),m={name:"llm/aeval-honesty-eval.md"};function h(p,a,C,F,D,u){const A=i("Mermaid");return l(),d("div",null,[a[2]||(a[2]=r('<h1 id="诚实性评测" tabindex="-1">诚实性评测 <a class="header-anchor" href="#诚实性评测" aria-label="Permalink to &quot;诚实性评测&quot;">​</a></h1><div class="epigraph"><p>诚实不是「答对了」，而是断言与知道的程度相称：把不确定说成确定，与把知道的说成不知道，是同一枚硬币的两面。</p><footer>—— Askell et al., 2021 把诚实列为独立于有用的轴；Kadavath et al., 2022 讨论模型知不知道自己知道</footer></div><p><a href="/llm/aeval-overrefusal-metric">上一课</a>把越权拒绝钉成对照集上的三分判分与帕累托工作点，无害轴有了镜子。诚实轴连攻击者都没有：失败藏在每一次自信的错误里，不出事就不留痕。<a href="/llm/honesty-citations">诚实与引用</a>在主干写过轴的来源；本课把诚实性评测拆成三层协议——事实、校准、弃权——外加引用忠实这一道缝。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>「诚实验证」若只考事实题，测到的是知识不是诚实：瞎猜碰对的模型同样拿高分，置信与正确脱节的失败完全不可见。反过来只考「敢说不知道」，会选出摆烂模型——把本可答对的题也弃权，与上一课的越权拒绝在产品侧是同一种体验。第三条缝是引用：断言挂着不存在的文献或与原文不符的出处，表面格式完全诚实，内容是伪造。三个缺口对应三套仪器：答案键、置信-正确耦合、断言-出处配对。</p><p><span class="marginnote">「校准」就是「自信程度与对错相称」：答十道题、每道都自称九成把握，那十道里就应该真对九道。自称九成把握结果只对五道，就是过度自信——这是模型最常见的诚实问题。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><h3 id="三层协议" tabindex="-1">三层协议 <a class="header-anchor" href="#三层协议" aria-label="Permalink to &quot;三层协议&quot;">​</a></h3><p><strong>事实层</strong>：带答案键的题集，可程序判定的子集（数值、抽取、代码）程序判，开放子集裁判加人工抽检，失败形态按<a href="/llm/hallucination-taxonomy">幻觉分类</a>分列；常见误解探针（TruthfulQA 一类）单独一张表，因为它测的是「会不会复读流行错误」。<strong>校准层</strong>：让模型报置信或用 token 概率，按置信分桶算期望校准误差 \\(\\mathrm{ECE}=\\sum_b \\frac{n_b}{N}\\,\\lvert \\mathrm{acc}_b-\\mathrm{conf}_b\\rvert\\)（口径见<a href="/llm/calibration-ece">校准与 ECE</a>）。<strong>弃权层</strong>：在置信阈值 \\(\\tau\\) 上扫描风险-覆盖曲线——\\(\\tau\\) 升则覆盖降、错误降；报曲线不报单点，协议见<a href="/llm/abstention-calibrated-refusal">弃权校准</a>。判分四分：对、错、弃权、拒答——弃权（承认不知道）与拒答（政策性不答）分列，否则越权拒绝会污染诚实分。<strong>引用层</strong>：抽断言-出处配对核验，协议位见<a href="/llm/citation-attribution">引用归因</a>。</p>',9)),(l(),n(s,null,{default:E(()=>[o(A,{id:"mermaid-25",class:"mermaid",graph:"flowchart%20TD%0A%20%20KEY%5B%22%E7%AD%94%E6%A1%88%E9%94%AE%E9%A2%98%E9%9B%86%22%5D%20--%3E%20GEN%5B%22%E7%94%9F%E6%88%90%20%2B%20%E7%BD%AE%E4%BF%A1%22%5D%0A%20%20GEN%20--%3E%20GRADE%5B%22%E7%A8%8B%E5%BA%8F%E5%88%A4%20%2F%20%E8%A3%81%E5%88%A4%EF%BC%9A%E5%AF%B9%20%2F%20%E9%94%99%20%2F%20%E5%BC%83%E6%9D%83%20%2F%20%E6%8B%92%E7%AD%94%22%5D%0A%20%20GRADE%20--%3E%20ECE%5B%22%E6%A0%A1%E5%87%86%EF%BC%9AECE%20%E4%B8%8E%E7%BD%AE%E4%BF%A1%E6%A1%B6%22%5D%0A%20%20ECE%20--%3E%20RC%5B%22%E9%A3%8E%E9%99%A9-%E8%A6%86%E7%9B%96%E6%9B%B2%E7%BA%BF%EF%BC%9A%E9%98%88%E5%80%BC%E6%89%AB%E6%8F%8F%22%5D%0A%20%20RC%20--%3E%20DOM%5B%22%E5%88%86%E5%9F%9F%E6%8A%A5%E5%91%8A%22%5D%0A%20%20GRADE%20--%3E%20REF%5B%22%E5%BC%95%E7%94%A8%E5%B1%82%EF%BC%9A%E6%96%AD%E8%A8%80-%E5%87%BA%E5%A4%84%E6%A0%B8%E9%AA%8C%22%5D%0A"})]),fallback:E(()=>[...a[0]||(a[0]=[t(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=e("h2",{id:"机制",tabindex:"-1"},[t("机制 "),e("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=e("p",null,"三个数必须耦合着报，机制在于它们此消彼长：准确率固定的题集上，弃权率升则错误率降——错误去哪了？变成可见的「不知道」。单报准确率奖励瞎猜，单报弃权率奖励摆烂，只有混淆表（对 / 错 / 弃权）加风险-覆盖曲线同时在场，模型才无法靠移动某一格刷分。训练侧的先验恰好反着来：SFT 与偏好数据系统性奖励「给出完整回答」，弃权被扣分，置信先验被推高——所以诚实评测要在训练各阶段各测一遍，差值才说明偏好训练把模型往哪边推。",-1)),a[5]||(a[5]=e("p",null,"弃权阈值一档一档移动时，「错误」这一格怎么搬进「弃权」：",-1)),(l(),n(s,null,{default:E(()=>[o(A,{id:"mermaid-35",class:"mermaid",graph:"flowchart%20LR%0A%20%20Q%5B%22%E4%B8%80%E9%81%93%E6%B2%A1%E6%8A%8A%E6%8F%A1%E7%9A%84%E9%A2%98%22%5D%20--%3E%7C%22%CF%84%20%E4%BD%8E%EF%BC%9A%E7%A1%AC%E7%AD%94%22%7C%20RIGHT%5B%22%E5%8F%AF%E8%83%BD%E5%AF%B9%EF%BC%8C%E4%B9%9F%E5%8F%AF%E8%83%BD%E9%94%99%22%5D%0A%20%20RIGHT%20--%3E%20WRONG%5B%22%E9%94%99%E4%BA%86%E8%AE%A1%E5%85%A5%E3%80%8C%E9%94%99%E3%80%8D%E6%A0%BC%22%5D%0A%20%20Q%20--%3E%7C%22%CF%84%20%E9%AB%98%EF%BC%9A%E8%AF%B4%E4%B8%8D%E7%9F%A5%E9%81%93%22%7C%20AB%5B%22%E8%AE%A1%E5%85%A5%E3%80%8C%E5%BC%83%E6%9D%83%E3%80%8D%E6%A0%BC%22%5D%0A%20%20AB%20--%3E%20SAFE%5B%22%E9%94%99%E8%AF%AF%E7%8E%87%E4%B8%8B%E9%99%8D%EF%BC%8C%E8%A6%86%E7%9B%96%E4%B9%9F%E4%B8%8B%E9%99%8D%22%5D%0A%20%20WRONG%20--%3E%20RISK%5B%22%E9%A3%8E%E9%99%A9-%E8%A6%86%E7%9B%96%E6%9B%B2%E7%BA%BF%EF%BC%9A%E4%B8%A4%E4%B8%AA%E8%AF%BB%E6%95%B0%E4%B8%80%E8%B5%B7%E7%9C%8B%22%5D%0A%20%20SAFE%20--%3E%20RISK%0A"})]),fallback:E(()=>[...a[1]||(a[1]=[t(" Loading... ",-1)])]),_:1})),a[6]||(a[6]=r('<p><span class="marginnote">只考核「敢说不知道」会选出摆烂模型：把会的题也弃权，弃权率好看但产品不可用；只考准确率则奖励瞎猜。两个指标必须捆在一起看——像考卷既看答对率、也看空题率，单独任何一个都能被刷分。</span></p><p><span class="marginnote">算一笔账就知道为什么耦合报是底线：一百题会七十题，剩下三十道四选一全瞎猜，期望再蒙对七道半——报告准确率约 77.5%。同一模型若被判分表保护着「不知道」，错误答案几乎消失。数字的差异来自判分表，不来自模型。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>诚实不等于展示无知：过度弃权是上一课越权拒绝的近亲，风险-覆盖曲线上工作点的选择要与安全帕累托一起定。开放生成没有答案键，诚实评测的覆盖天然不全，只宣称「在固定键集上的弃权-错误结构」，不宣称「已消除幻觉」。答案键有时效：世界变了，旧键失效，题集要带版本与日期。最后，裁判对流畅长答的偏爱会伪装成诚实——校准层用程序判的子集做锚，别让文风替模型认错。</p><p><span class="marginnote">答案键有时效性：「某公司的 CEO 是谁」「现任某职位的是谁」这类题的正确答案每年都变。拿三年前的答案键测今天的模型，会把「模型没说错」误判成「模型在胡说」——所以题集必须带版本与日期。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>诚实的最小单位是「断言 × 置信 × 真值」三者相称，不是单独的准确率。</li><li>四分判分：对、错、弃权、拒答；弃权与政策性拒答必须分列。</li><li>ECE 与风险-覆盖曲线耦合报，单格刷分无利可图。</li><li>引用忠实单独一层：格式诚实的伪造出处不算诚实。</li><li>训练各阶段分别测量：偏好训练对置信先验的推动要有自己的数字。</li><li>出处：Askell et al., 2021；Kadavath et al., 2022；TruthfulQA、SimpleQA 一类公开键集的口径。</li></ul>',7))])}const _=B(m,[["render",h]]);export{c as __pageData,_ as default};
